import unittest

def score_label(score):
    return 'pass' if score >= 70 else 'review'

class ScoreTests(unittest.TestCase):
    def test_below_boundary(self):
        self.assertEqual(score_label(69), 'review')

    def test_at_boundary(self):
        self.assertEqual(score_label(70), 'pass')

    def test_above_boundary(self):
        self.assertEqual(score_label(100), 'pass')

suite = unittest.defaultTestLoader.loadTestsFromTestCase(ScoreTests)
result = unittest.TestResult()
suite.run(result)
assert result.testsRun == 3
assert result.wasSuccessful(), result.errors + result.failures
print('three threshold checks passed')
